// Só interessa mensagem que o contato mandou na caixa do WhatsApp da V2O5,
// repassada pelo fluxo da origem (o Chatwoot não entrega message_created ao
// agent bot nesta instalação; o evento direto do bot é ignorado, para a mesma
// mensagem nunca ser respondida duas vezes). O endereço do webhook é público:
// o resto do fluxo relê tudo pela API do Chatwoot e usa daqui só os números
// (conversa, contato, mensagem).
const cfg = $("Configuração").first().json;
const evento = $input.first().json.body || {};
const conversa = evento.conversation || {};
const recebida = evento.message_type === "incoming" || evento.message_type === 0;
const daConta = String(evento.account?.id) === String(cfg.chatwootConta);
const daCaixa = String(conversa.inbox_id ?? evento.inbox?.id) === String(cfg.chatwootInbox);
const contatoId = conversa.meta?.sender?.id ?? evento.sender?.id;
if (evento.event !== "message_created" || evento.repasse !== "origem" || !recebida || evento.private || !daConta || !daCaixa || !conversa.id || !contatoId) return [];
return [{
  json: {
    conversaId: conversa.id,
    contatoId,
    mensagemId: evento.id,
    texto: String(evento.content ?? ""),
    rotulosDaConversa: Array.isArray(conversa.labels) ? conversa.labels : [],
  },
}];

// O agente só fala com lead que veio do site ou de um link de diagnóstico:
// contato marcado com origem na V2O5 (formulário ou botão), conversa
// etiquetada, ou primeira mensagem da conversa com a mensagem pronta do site
// ("site da V2O5") ou da página de diagnóstico ("Vi o diagnóstico da").
// Conversa de outro contato vai para "aberta", sem resposta, para a equipe.
const cfg = $("Configuração").first().json;
const ev = $("Mensagem recebida").first().json;
const conversa = $("Conversa").first().json;
const contato = $("Contato").first().json.payload || {};
const mensagens = (Array.isArray($("Mensagens da conversa").first().json.payload) ? $("Mensagens da conversa").first().json.payload : [])
  .slice()
  .sort((a, b) => Number(a.id) - Number(b.id));
const semAcento = (t) => String(t ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
const recebida = (m) => (m.message_type === 0 || m.message_type === "incoming") && !m.private;
const enviada = (m) => (m.message_type === 1 || m.message_type === "outgoing") && !m.private;

// Só conversa pendente é do agente; aberta, resolvida ou com gente atribuída
// já é da equipe.
if (conversa.status !== "pending") return [];
// O evento vem de um endereço público: conversa e contato precisam bater com
// o que a API diz.
if (String(conversa.inbox_id) !== String(cfg.chatwootInbox) || Number(conversa.meta?.sender?.id) !== Number(ev.contatoId)) return [];
const tipoAtribuido = conversa.meta?.assignee_type;
if (conversa.meta?.assignee && tipoAtribuido !== "AgentBot") return [];

// Várias mensagens seguidas: responde uma vez, no evento da última.
const conversaveis = mensagens.filter((m) => recebida(m) || enviada(m));
const ultima = conversaveis[conversaveis.length - 1];
if (!ultima || !recebida(ultima) || Number(ultima.id) !== Number(ev.mensagemId)) return [];

const primeiraRecebida = mensagens.find(recebida);
const doDiagnostico =
  semAcento((contato.custom_attributes || {}).entrada) === semAcento("link do diagnóstico") ||
  (primeiraRecebida !== undefined && semAcento(primeiraRecebida.content).includes(semAcento(cfg.marcaDoDiagnostico)));
const marcado =
  semAcento((contato.custom_attributes || {})[cfg.atributoOrigem]) === semAcento(cfg.valorOrigem) ||
  (conversa.labels || []).includes(cfg.etiquetaOrigem) ||
  (primeiraRecebida !== undefined && semAcento(primeiraRecebida.content).includes(semAcento(cfg.marcaDoSite))) ||
  doDiagnostico;

return [{ json: { acao: marcado ? "responder" : "passar", conversaId: ev.conversaId, contatoId: ev.contatoId, entrada: doDiagnostico ? "diagnostico" : "site" } }];

// Monta o pedido à Chat Completions da OpenAI: instruções e conhecimento (o
// llms.txt do site, a mesma fonte dos preços publicados) na primeira mensagem
// de sistema, que não muda entre conversas e entra no cache automático da
// OpenAI; os dados do contato numa segunda, à parte; a conversa como histórico.
const cfg = $("Configuração").first().json;
const contato = $("Contato").first().json.payload || {};
const mensagens = (Array.isArray($("Mensagens da conversa").first().json.payload) ? $("Mensagens da conversa").first().json.payload : [])
  .slice()
  .sort((a, b) => Number(a.id) - Number(b.id));
const conhecimento = typeof $input.first().json.data === "string" ? $input.first().json.data.trim() : "";

const INSTRUCOES = "Você atende o WhatsApp da V2O5 Vendas e Tecnologia. Quem escreve chegou pelo site da V2O5 (pelo formulário do diagnóstico ou pelo botão de WhatsApp de uma das páginas) ou pelo link de um diagnóstico de presença digital que o Dyones mandou para a empresa.\n\nA V2O5 identifica gargalos de operações comerciais e administrativas, simplifica processos e implementa tecnologia, automação e IA (site, rastreamento, agente no WhatsApp e CRM) para reduzir atrito e tornar os resultados mensuráveis. Oferta principal: Sprint de Eficiência, com preço fechado em proposta depois de delimitar o gargalo. O fundador é o Dyones Oliveira, que conduz o diagnóstico.\n\nSeu objetivo é entender o que a pessoa precisa e levá-la ao diagnóstico gratuito: uma sessão inicial de 45 minutos com o Dyones, que identifica e prioriza um gargalo. Ela não inclui mapeamento completo, implementação nem acompanhamento, e não promete mapa nem prazo de entrega.\n\nQuem veio do link do diagnóstico já recebeu o diagnóstico da empresa e quer falar dos próximos passos: não ofereça o diagnóstico gratuito de novo. Agradeça, pergunte o melhor dia e horário para conversar com o Dyones e passe para a equipe. Se a pessoa disser qual caminho quer seguir, passe para a equipe na hora.\n\nComo escrever\n- Português do Brasil, cordial e direto, como alguém da equipe escreveria no WhatsApp.\n- No máximo três frases por mensagem e uma pergunta por vez.\n- Sem travessão, sem lista, sem negrito ou markdown. Emoji só se a pessoa usar, e no máximo um.\n- Chame a pessoa pelo primeiro nome quando souber.\n- Se perguntarem, diga que é o assistente virtual da V2O5 e que o Dyones acompanha a conversa.\n\nO que perguntar, aos poucos e só o que faltar: o nome da empresa, o segmento e o que a pessoa quer resolver primeiro. Use os dados do contato para não repetir pergunta.\n\nFatos e preços\n- Fale só do que está no conhecimento abaixo. Só o Sprint de Eficiência e a recorrência que o acompanha (estabilidade e suporte, evolução contínua) têm valor público: cite apenas os valores que aparecem lá (o valor de partida de cada Sprint, sem falar em teto, e a faixa mensal da recorrência), dizendo que o preço fechado sai em proposta e que, se a solução continua rodando, há uma parte recorrente em contrato à parte: a gestão continuada está na faixa mensal, e a nuvem e a IA ficam por fora, pelo valor do provedor, e a V2O5 gerencia as duas; o consumo de IA e de mensagens pode ter teto mensal combinado, com aviso antes de ultrapassá-lo. Não explique de quem são as contas; fale só em recorrência. Nunca cite valor de plano, módulo ou serviço avulso; diga que o Dyones confirma no diagnóstico.\n- Não invente número, prazo, desconto, cliente ou resultado. Número do case Motors Store só como está no conhecimento.\n- Se a resposta não estiver no conhecimento, diga que o Dyones confirma no diagnóstico. Se o conhecimento estiver vazio, não fale de preço.\n- Nunca peça CPF, senha, cartão ou documento.\n\nQuando passar para a equipe (passar_para_humano = true)\n- A pessoa pede para falar com alguém, com o Dyones ou por ligação.\n- A pessoa sugere dia e horário para o diagnóstico ou pede para marcar. Responda que anotou e que o Dyones confirma o horário por aqui.\n- Negociação de preço, desconto, contrato, proposta formal ou forma de pagamento.\n- Cliente atual pedindo suporte, reclamação, fornecedor, vaga de emprego ou assunto fora do que a V2O5 vende.\n- Mensagem só com áudio, imagem ou arquivo: peça para escrever em texto; se já pediu antes, passe.\n- Quando estiver em dúvida.\nAo passar, escreva em nota_para_equipe uma linha para o Dyones com quem é, o que quer e por que passou. A resposta ao contato pode ficar vazia se não houver nada útil a dizer.\n\nResponda só com o JSON pedido.";
const ESQUEMA = {"type": "object", "properties": {"resposta": {"type": "string", "description": "Mensagem para o contato no WhatsApp. Pode ficar vazia ao passar para a equipe."}, "passar_para_humano": {"type": "boolean", "description": "true quando a conversa deve ir para a equipe."}, "nota_para_equipe": {"type": "string", "description": "Uma linha para o Dyones ao passar: quem é, o que quer, por que passou. Vazia se não passar."}}, "required": ["resposta", "passar_para_humano", "nota_para_equipe"], "additionalProperties": false};

const recebida = (m) => (m.message_type === 0 || m.message_type === "incoming") && !m.private;
const enviada = (m) => (m.message_type === 1 || m.message_type === "outgoing") && !m.private;
const textoDa = (m) => {
  const texto = String(m.content ?? "").trim();
  if (texto) return texto;
  const anexos = (m.attachments || []).map((a) => a.file_type || "arquivo");
  return anexos.length ? "[enviou " + anexos.join(", ") + "]" : "";
};

const linhas = mensagens
  .filter((m) => recebida(m) || enviada(m))
  .slice(-Number(cfg.mensagensNoHistorico || 30))
  .map((m) => ({ role: recebida(m) ? "user" : "assistant", content: textoDa(m) }))
  .filter((l) => l.content);
// O histórico começa pelo contato. Quando quem abriu foi a V2O5 (a resposta
// ao formulário), um aviso curto ocupa esse lugar.
if (linhas.length && linhas[0].role === "assistant") {
  linhas.unshift({ role: "user", content: "[A conversa começou com a mensagem da V2O5 abaixo.]" });
}
const historico = [];
for (const l of linhas) {
  const anterior = historico[historico.length - 1];
  if (anterior && anterior.role === l.role) anterior.content += "\n" + l.content;
  else historico.push({ ...l });
}

const a = contato.custom_attributes || {};
const hoje = new Date().toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" });
const dados = [
  "Dados do contato no Chatwoot (podem estar incompletos):",
  "Nome: " + (contato.name || "não informado"),
  a.empresa ? "Empresa: " + a.empresa : "",
  a.segmento ? "Segmento: " + a.segmento : "",
  a.porte ? "Porte: " + a.porte : "",
  a.objetivos ? "Objetivos: " + a.objetivos : "",
  a.estoque ? "Estoque: " + a.estoque : "",
  a.sistema ? "Sistema: " + a.sistema : "",
  a.entrada ? "Entrada: " + a.entrada : "",
  a.pagina ? "Página: " + a.pagina : "",
  $("Decidir").first().json.entrada === "diagnostico" ? "Veio do link do diagnóstico de presença digital." : "",
  "Hoje: " + hoje,
].filter(Boolean).join("\n");

const corpo = {
  model: cfg.modeloIA,
  reasoning_effort: cfg.esforcoIA,
  max_completion_tokens: 8000,
  response_format: { type: "json_schema", json_schema: { name: "resposta_do_agente", strict: true, schema: ESQUEMA } },
  messages: [
    { role: "system", content: INSTRUCOES + "\n\n# Conhecimento (site da V2O5)\n\n" + (conhecimento || "(vazio)") },
    { role: "system", content: dados },
    ...historico,
  ],
};
return [{ json: { corpo } }];

// Lê a saída estruturada. Recusa, erro da API, resposta cortada ou JSON fora
// do formato: nada vai para o contato e a conversa passa para a equipe com uma nota.
const r = $input.first().json || {};
const escolha = Array.isArray(r.choices) ? r.choices[0] || {} : {};
const mensagem = escolha.message || {};
let saida = null;
if (!mensagem.refusal && escolha.finish_reason === "stop" && typeof mensagem.content === "string") {
  try {
    saida = JSON.parse(mensagem.content);
  } catch (e) {
    saida = null;
  }
}
if (!saida || typeof saida.resposta !== "string") {
  const motivo = r.error?.message || (mensagem.refusal ? "recusa" : escolha.finish_reason) || "resposta fora do formato";
  return [{ json: { resposta: "", passar: true, nota: "O agente não respondeu (" + motivo + "). A conversa ficou aberta para a equipe." } }];
}
// Regra do texto público da V2O5: sem travessão.
const resposta = saida.resposta.replace(/\s*[—–]\s*/g, ", ").trim();
return [{ json: { resposta, passar: saida.passar_para_humano === true || !resposta, nota: String(saida.nota_para_equipe || "").trim() } }];
